from __future__ import annotations

"""Font model used by the subsetting pipeline.

A ``GlyphFont`` carries the three tables the subsetter cares about:

* ``cmap`` maps a Unicode code point to a glyph id. A code point with no
  entry is unmapped and falls back to ``.notdef`` (glyph id 0).
* ``ligatures`` are GSUB-style rules. Each rule has an ordered ``components``
  list of glyph ids that, when they appear back to back in the run, are
  replaced by a single ``ligature`` glyph id (f + i -> the "fi" glyph).
* ``marks`` are combining-accent rules. A ``base`` glyph id followed by a
  combining code point produces a ``mark`` glyph id that must travel with the
  base so the accent renders.

Glyph id 0 is reserved for ``.notdef`` (the missing-glyph box). Every real
font ships it, and any subset of a font must keep it.
"""

from dataclasses import dataclass, field

NOTDEF_GID = 0


@dataclass(frozen=True)
class LigatureRule:
    components: tuple[int, ...]
    ligature: int

    def __post_init__(self) -> None:
        if len(self.components) < 2:
            raise ValueError("a ligature needs at least two components")
        if self.ligature == NOTDEF_GID:
            raise ValueError("ligature glyph cannot be .notdef")

    def matches_at(self, run: list[int], index: int) -> bool:
        end = index + len(self.components)
        if end > len(run):
            return False
        return tuple(run[index:end]) == self.components

    def length(self) -> int:
        return len(self.components)


@dataclass(frozen=True)
class MarkRule:
    base: int
    combining_cp: int
    mark: int

    def __post_init__(self) -> None:
        if self.mark == NOTDEF_GID:
            raise ValueError("mark glyph cannot be .notdef")


@dataclass
class GlyphFont:
    family: str
    cmap: dict[int, int] = field(default_factory=dict)
    ligatures: list[LigatureRule] = field(default_factory=list)
    marks: list[MarkRule] = field(default_factory=list)

    def __post_init__(self) -> None:
        if not self.family.strip():
            raise ValueError("family is required")
        # .notdef is implicit; callers never map a code point onto it.
        if NOTDEF_GID in self.cmap.values():
            raise ValueError("cmap must not point a code point at .notdef")

    def has_glyph(self, gid: int) -> bool:
        if gid == NOTDEF_GID:
            return True
        if gid in self.cmap.values():
            return True
        if any(rule.ligature == gid for rule in self.ligatures):
            return True
        return any(rule.mark == gid for rule in self.marks)

    def gid_for_codepoint(self, cp: int) -> int:
        return self.cmap.get(cp, NOTDEF_GID)

    def is_mapped(self, cp: int) -> bool:
        return cp in self.cmap

    def ligature_rules_sorted(self) -> list[LigatureRule]:
        # Longest component runs first so "ffi" wins over "fi".
        return sorted(self.ligatures, key=lambda r: r.length(), reverse=True)

    def mark_for(self, base_gid: int, combining_cp: int) -> int | None:
        for rule in self.marks:
            if rule.base == base_gid and rule.combining_cp == combining_cp:
                return rule.mark
        return None

    def all_real_glyphs(self) -> set[int]:
        glyphs: set[int] = {NOTDEF_GID}
        glyphs.update(self.cmap.values())
        glyphs.update(rule.ligature for rule in self.ligatures)
        glyphs.update(rule.mark for rule in self.marks)
        return glyphs


def is_combining(cp: int) -> bool:
    """Combining marks live in the Unicode combining-diacritical range."""

    return 0x0300 <= cp <= 0x036F


def codepoints(text: str) -> list[int]:
    return [ord(ch) for ch in text]

