from __future__ import annotations

"""Build the minimal glyph subset for an exported PDF.

When InDesign exports a PDF it does not embed the whole font. It embeds a
subset: only the glyphs the document actually needs. A correct subset is the
*closure* of the document text under the font's substitution tables:

* every glyph the text maps to directly,
* every glyph reachable through ligature substitution,
* every combining-mark glyph the text pulls in,
* and ``.notdef``, which every embedded font keeps.

This module collects that subset from one or more text runs and reports it as
a ``GlyphSubset``. Downstream the export check renders each run against the
subset to confirm nothing fell out.
"""

from dataclasses import dataclass, field

from font_model import GlyphFont, NOTDEF_GID, is_combining
from text_shaping import required_glyphs


@dataclass
class GlyphSubset:
    font_family: str
    gids: set[int] = field(default_factory=set)

    def __post_init__(self) -> None:
        # A subset that forgot .notdef cannot render a missing glyph safely.
        self.gids.add(NOTDEF_GID)

    def contains(self, gid: int) -> bool:
        return gid in self.gids

    def size(self) -> int:
        return len(self.gids)

    def sorted_gids(self) -> list[int]:
        return sorted(self.gids)

    def covers(self, needed: set[int]) -> bool:
        return needed.issubset(self.gids)

    def missing_from(self, needed: set[int]) -> set[int]:
        return needed - self.gids


def _collect_literal_gids(font: GlyphFont, text: str) -> set[int]:
    """Glyph ids the cmap assigns to the literal, unshaped characters."""

    gids: set[int] = set()
    for ch in text:
        cp = ord(ch)
        if is_combining(cp):
            continue
        gids.add(font.gid_for_codepoint(cp))
    return gids


def subset_for_text(font: GlyphFont, text: str) -> GlyphSubset:
    """Subset needed to render a single run of text."""

    collected = _collect_literal_gids(font, text)
    return GlyphSubset(font_family=font.family, gids=collected)


def subset_for_runs(font: GlyphFont, runs: list[str]) -> GlyphSubset:
    """Subset needed to render several runs from the same document."""

    collected: set[int] = set()
    for run in runs:
        collected |= _collect_literal_gids(font, run)
    return GlyphSubset(font_family=font.family, gids=collected)


def subset_gids_for_text(font: GlyphFont, text: str) -> list[int]:
    return subset_for_text(font, text).sorted_gids()


def subset_size_for_runs(font: GlyphFont, runs: list[str]) -> int:
    return subset_for_runs(font, runs).size()


def merge_subsets(font: GlyphFont, subsets: list[GlyphSubset]) -> GlyphSubset:
    merged: set[int] = set()
    for sub in subsets:
        merged |= sub.gids
    return GlyphSubset(font_family=font.family, gids=merged)


def subset_covers_text(font: GlyphFont, text: str) -> bool:
    """Whether the built subset actually covers what the text needs."""

    subset = subset_for_text(font, text)
    return subset.covers(required_glyphs(font, text))


def describe_subset(font: GlyphFont, text: str) -> dict[str, object]:
    subset = subset_for_text(font, text)
    needed = required_glyphs(font, text)
    return {
        "font_family": font.family,
        "subset_gids": subset.sorted_gids(),
        "subset_size": subset.size(),
        "needed_gids": sorted(needed),
        "missing_gids": sorted(subset.missing_from(needed)),
        "has_notdef": subset.contains(NOTDEF_GID),
    }

