from __future__ import annotations

"""Verify an exported PDF would render text without missing-glyph boxes.

"Tofu" is the empty rectangle a PDF viewer draws when a positioned glyph is
not in the embedded subset. The shaping pass already knows exactly which glyph
ids each run needs. Rendering against a subset just walks those shaped glyphs
and asks: is this glyph embedded? If a needed glyph is absent, the renderer
falls back to ``.notdef`` and the reader sees a box.

A run is clean only when every shaped glyph it draws is present in the subset,
with the single exception of glyphs that were already ``.notdef`` in shaping
(genuinely unmapped input, which is the author's problem, not the subset's).
"""

from dataclasses import dataclass, field

from font_model import GlyphFont, NOTDEF_GID
from glyph_subsetter import GlyphSubset, subset_for_runs
from text_shaping import ShapedGlyph, shape_text


@dataclass
class RenderedGlyph:
    requested_gid: int
    drawn_gid: int
    is_tofu: bool
    source: str


@dataclass
class RenderResult:
    run: str
    glyphs: list[RenderedGlyph] = field(default_factory=list)

    def tofu_count(self) -> int:
        return sum(1 for g in self.glyphs if g.is_tofu)

    def has_tofu(self) -> bool:
        return self.tofu_count() > 0

    def drawn_gids(self) -> list[int]:
        return [g.drawn_gid for g in self.glyphs]

    def tofu_positions(self) -> list[int]:
        return [i for i, g in enumerate(self.glyphs) if g.is_tofu]


def render_with_subset(font: GlyphFont, subset: GlyphSubset, text: str) -> RenderResult:
    shaped = shape_text(font, text)
    result = RenderResult(run=text)
    for glyph in shaped.glyphs:
        result.glyphs.append(_render_one(subset, glyph))
    return result


def _render_one(subset: GlyphSubset, glyph: ShapedGlyph) -> RenderedGlyph:
    # A glyph that shaping already marked as .notdef is not the subset's fault.
    if glyph.gid == NOTDEF_GID:
        return RenderedGlyph(
            requested_gid=glyph.gid,
            drawn_gid=NOTDEF_GID,
            is_tofu=False,
            source=glyph.source,
        )
    if subset.contains(glyph.gid):
        return RenderedGlyph(
            requested_gid=glyph.gid,
            drawn_gid=glyph.gid,
            is_tofu=False,
            source=glyph.source,
        )
    # Needed glyph missing from the subset -> viewer draws a box.
    return RenderedGlyph(
        requested_gid=glyph.gid,
        drawn_gid=NOTDEF_GID,
        is_tofu=True,
        source=glyph.source,
    )


def export_is_clean(font: GlyphFont, text: str) -> bool:
    """Build the subset the exporter would and check the run renders cleanly."""

    subset = subset_for_runs(font, [text])
    return not render_with_subset(font, subset, text).has_tofu()


def verify_document(font: GlyphFont, runs: list[str]) -> dict[str, object]:
    """Render every run against the shared document subset; report tofu."""

    subset = subset_for_runs(font, runs)
    results = [render_with_subset(font, subset, run) for run in runs]
    total_tofu = sum(r.tofu_count() for r in results)
    return {
        "font_family": font.family,
        "subset_size": subset.size(),
        "run_count": len(runs),
        "total_tofu": total_tofu,
        "clean": total_tofu == 0,
        "tofu_runs": [r.run for r in results if r.has_tofu()],
    }


def tofu_gids_for_run(font: GlyphFont, runs: list[str], target_run: str) -> list[int]:
    subset = subset_for_runs(font, runs)
    result = render_with_subset(font, subset, target_run)
    return sorted({g.requested_gid for g in result.glyphs if g.is_tofu})

