from __future__ import annotations

"""Shaping pass: turn a string into the glyph run a renderer would draw.

Shaping is the step between "here is some text" and "here are the glyphs on
the page". It does three things in order:

1. Map every code point through the cmap to a base glyph id.
2. Apply ligature substitutions: a matching component run collapses into the
   single ligature glyph (longest match wins, e.g. "ffi" before "fi").
3. Attach combining marks: a combining code point after a base glyph becomes
   the mark glyph for that (base, combining) pair.

The result is a ``ShapedRun`` listing the glyph ids that actually get drawn,
plus the set of every glyph id those draws touch. That coverage set is the
ground truth a subset has to satisfy.
"""

from dataclasses import dataclass, field

from font_model import GlyphFont, NOTDEF_GID, is_combining


@dataclass
class ShapedGlyph:
    gid: int
    source: str  # "cmap", "ligature", "mark", or "notdef"


@dataclass
class ShapedRun:
    glyphs: list[ShapedGlyph] = field(default_factory=list)

    def gids(self) -> list[int]:
        return [g.gid for g in self.glyphs]

    def coverage(self) -> set[int]:
        """Every glyph id this run draws (always includes .notdef)."""

        covered = {NOTDEF_GID}
        covered.update(g.gid for g in self.glyphs)
        return covered

    def has_notdef(self) -> bool:
        return any(g.gid == NOTDEF_GID for g in self.glyphs)


def _map_codepoints(font: GlyphFont, cps: list[int]) -> list[ShapedGlyph]:
    """Raw cmap pass before ligatures and marks. Marks are kept as-is here."""

    mapped: list[ShapedGlyph] = []
    for cp in cps:
        if is_combining(cp):
            # Combining marks resolve against the preceding base later.
            mapped.append(ShapedGlyph(gid=cp, source="combining"))
            continue
        gid = font.gid_for_codepoint(cp)
        source = "cmap" if gid != NOTDEF_GID else "notdef"
        mapped.append(ShapedGlyph(gid=gid, source=source))
    return mapped


def _apply_marks(font: GlyphFont, glyphs: list[ShapedGlyph]) -> list[ShapedGlyph]:
    out: list[ShapedGlyph] = []
    for glyph in glyphs:
        if glyph.source == "combining":
            if not out:
                out.append(ShapedGlyph(gid=NOTDEF_GID, source="notdef"))
                continue
            base = out[-1]
            mark_gid = font.mark_for(base.gid, glyph.gid)
            if mark_gid is None:
                out.append(ShapedGlyph(gid=NOTDEF_GID, source="notdef"))
            else:
                out.append(ShapedGlyph(gid=mark_gid, source="mark"))
        else:
            out.append(glyph)
    return out


def _apply_ligatures(font: GlyphFont, glyphs: list[ShapedGlyph]) -> list[ShapedGlyph]:
    run = [g.gid for g in glyphs]
    rules = font.ligature_rules_sorted()
    out: list[ShapedGlyph] = []
    i = 0
    while i < len(run):
        matched = False
        for rule in rules:
            if rule.matches_at(run, i):
